    LVMS = LVMALL[l * 4 + 2];
    prep_AO(0);
    LVS = LVALL[l * 4 + 2];
    tablesD();
    M = WALL[l * 4 + 2];
    MP = 2;
    rowsChunked(D, NBD);
    sparseFix(l * 4 + 2);
